{"cards": [{"node_code": "N_8552149f61e646aa", "definition": "研究非钢质材料（如铝、木、玻璃钢、塑料、水泥等）船体的成型、连接、装配及表面处理等专用制造工艺与技术。", "boundary": "本节点聚焦于“非钢质”材料的船体制造。边界在于区分“钢质船体”（归入放样、焊接等通用工艺节点）与“其他材料”。若内容涉及复合材料或特种金属的船体结构设计与制造方法，归入本节点。若仅涉及材料本身的化学性质研究而非船体制造，需视具体学科归属。", "includes": ["铝质、木质、玻璃钢、塑料及水泥船体的成型与连接工艺", "非钢质船体的装配、舾装及表面处理技术", "特种材料船体的制造工艺优化与质量控制"], "excludes": ["钢质船体的放样、切割、焊接及装配工艺", "船舶总体设计、结构计算及原理研究", "非船体用途的通用材料加工工艺"], "sibling_distinctions": [{"other_code": "N_1a2ddd9128f191b4", "rule": "放样、号料、切割主要指钢质船体的下料工艺，本节点针对非钢质材料的特定成型与加工。"}, {"other_code": "N_57afbe4abe471761", "rule": "焊接与其他连接工艺主要指钢质船体的连接，本节点涵盖非钢质材料特有的连接方式（如粘接、铆接、螺栓连接等）。"}], "cross_boundary_rule": "若内容涉及钢铝混合船体的制造工艺，侧重钢质部分归入通用工艺，侧重铝质部分归入本节点；若侧重整体结构连接，可关联焊接与其他连接工艺。"}, {"node_code": "N_57afbe4abe471761", "definition": "研究船舶建造中焊接、铆接、粘接等连接方法的工艺规范、设备选用、材料特性及焊缝质量检验与控制技术。", "boundary": "本节点聚焦于“连接工艺”及其质量控制。边界在于区分“连接方法”与“船体装配”（侧重结构组合）、“表面处理”（侧重防腐）。若内容涉及焊接设备的设计原理，侧重工艺应用归入本节点，侧重机械设计可关联相关工程节点。", "includes": ["船舶焊接工艺（电弧焊、气保焊等）及设备、材料选用", "铆接、粘接、螺栓连接等非焊接连接工艺", "焊缝缺陷分析、无损检测及焊接质量控制"], "excludes": ["船体放样、号料、切割等下料工艺", "船体分段装配、胎架制作及总装工艺", "船舶舾装件的安装与调试"], "sibling_distinctions": [{"other_code": "N_ec880622b3a6a757", "rule": "船体装配和胎架侧重结构组合与支撑，本节点侧重连接点的质量与工艺方法。"}, {"other_code": "N_a06564e7de56db2d", "rule": "钢料除锈及表面清理是焊接前的准备工序，本节点侧重连接过程本身及后续检验。"}], "cross_boundary_rule": "若内容涉及焊接工艺对船体结构强度的影响，主挂载本节点；若侧重结构计算，可关联船舶工程。"}, {"node_code": "N_f8e4493729f84c9f", "definition": "研究船舶主机、辅机、管系、电气设备及舾装件的制造、安装、调试工艺，以及造船木工、电镀喷涂等装饰与绝缘工艺。", "boundary": "本节点聚焦于“舾装”阶段，即船体结构完工后的设备安装与内部装修。边界在于区分“舾装”与“船体建造”（侧重结构）、“船舶工程”（侧重系统设计）。若内容涉及设备本身的研发设计，归入相关设备学科；若侧重安装工艺，归入本节点。", "includes": ["主机、推进器、轴系及辅机的安装与调试工艺", "管系加工安装、电气电信设备安装及调试", "造船木工、电镀、喷涂装饰及绝缘工艺"], "excludes": ["船体结构焊接、装配及下水工艺", "船舶总体设计、系统原理及性能研究", "设备本身的研发、制造及非船舶用途应用"], "sibling_distinctions": [{"other_code": "N_ec880622b3a6a757", "rule": "船体装配侧重船体结构本身的组合，本节点侧重船体内部设备及舾装件的安装。"}, {"other_code": "N_57afbe4abe471761", "rule": "焊接与其他连接工艺侧重船体结构的连接，本节点侧重设备与船体、设备与设备之间的安装连接。"}], "cross_boundary_rule": "若内容涉及舾装工艺对船舶整体性能的影响，主挂载本节点；若侧重系统性能优化，可关联船舶工程。"}]}
